#include <iostream>
#include <map>
#include <string>
int main() {
    std::multimap<int, std::string> myMap = {{1, "one"}, {2, "two"}, {3, "three"}};
    // Using a different key type (e.g., long) with template find
    auto it = myMap.find(2L); // long implicitly converts to int
    if (it != myMap.end()) {
        std::cout << "Found: " << it->second << std::endl;
    }
    // Using template find with a custom type that can convert to int
    struct MyKey {
        long value;
        operator int() const { return static_cast<int>(value); }
    };
    MyKey key{2};
    auto it2 = myMap.find(key);
    if (it2 != myMap.end()) {
        std::cout << "Found via custom key: " << it2->second << std::endl;
    }
    return 0;
}
